<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Database;use App\Core\View;use App\Services\UploadService;

final class IssueController
{
    public function index():void{$where=["i.moderation_status='approved'","i.deleted_at IS NULL"];$p=[];if($c=(int)($_GET['category']??0)){$where[]='i.category_id=?';$p[]=$c;}if($l=trim($_GET['locality']??'')){$where[]='i.locality LIKE ?';$p[]='%'.$l.'%';}$issues=Database::all('SELECT i.*,c.name category,(SELECT COUNT(*) FROM issue_supports s WHERE s.issue_id=i.id) supports FROM civic_issues i JOIN issue_categories c ON c.id=i.category_id WHERE '.implode(' AND ',$where).' ORDER BY i.published_at DESC LIMIT 50',$p);$categories=Database::all('SELECT * FROM issue_categories WHERE is_active=1 ORDER BY position');View::render('issues/index',compact('issues','categories'));}
    public function show(string $slug):void{$issue=Database::one("SELECT i.*,c.name category,u.full_name,(SELECT COUNT(*) FROM issue_supports s WHERE s.issue_id=i.id) supports FROM civic_issues i JOIN issue_categories c ON c.id=i.category_id JOIN users u ON u.id=i.user_id WHERE i.slug=? AND i.moderation_status='approved' AND i.deleted_at IS NULL",[$slug]);if(!$issue){http_response_code(404);View::render('errors/404',['title'=>'Issue not found']);return;}$history=Database::all('SELECT h.*,u.full_name actor FROM issue_status_history h JOIN users u ON u.id=h.actor_id WHERE h.issue_id=? AND h.public_update IS NOT NULL ORDER BY h.created_at DESC',[$issue['id']]);$comments=Database::all("SELECT c.*,u.full_name FROM issue_comments c JOIN users u ON u.id=c.user_id WHERE c.issue_id=? AND c.status='approved' AND c.deleted_at IS NULL ORDER BY c.created_at",[$issue['id']]);View::render('issues/show',compact('issue','history','comments'));}
    public function create():void{Auth::requireLogin();$categories=Database::all('SELECT * FROM issue_categories WHERE is_active=1 ORDER BY position');View::render('issues/create',compact('categories'));}
    public function store():void{Auth::requireLogin();$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$category=(int)($_POST['category_id']??0);$locality=trim($_POST['locality']??'');if(mb_strlen($title)<8||mb_strlen($desc)<30||!$category||!$locality){$_SESSION['_old']=$_POST;flash('error','Please provide a clear title, category, locality and detailed description.');redirect('issues/create');}$slug=$this->slug($title).'-'.bin2hex(random_bytes(3));Database::connection()->beginTransaction();try{Database::run('INSERT INTO civic_issues(user_id,category_id,title,slug,description,locality,ward,location_description) VALUES(?,?,?,?,?,?,?,?)',[auth()['id'],$category,$title,$slug,$desc,$locality,trim($_POST['ward']??''),trim($_POST['location_description']??'')]);$id=Database::id();if(isset($_FILES['evidence'])){$file=(new UploadService())->store($_FILES['evidence'],'issues');if($file)Database::run('INSERT INTO issue_media(issue_id,file_path,original_name,mime_type,file_size) VALUES(?,?,?,?,?)',[$id,$file['path'],$file['original'],$file['mime'],$file['size']]);}Database::run('INSERT INTO issue_status_history(issue_id,actor_id,new_status,public_update) VALUES(?,?,?,?)',[$id,auth()['id'],'reported','Issue submitted for moderation.']);Database::connection()->commit();}catch(\Throwable $e){Database::connection()->rollBack();throw $e;}flash('success','Your issue was submitted for moderation.');redirect('account');}
    public function support(string $id):void{Auth::requireLogin();$sqlite=Database::connection()->getAttribute(\PDO::ATTR_DRIVER_NAME)==='sqlite';Database::run($sqlite?'INSERT OR IGNORE INTO issue_supports(issue_id,user_id) VALUES(?,?)':'INSERT IGNORE INTO issue_supports(issue_id,user_id) VALUES(?,?)',[(int)$id,auth()['id']]);flash('success','Your support has been recorded.');redirect('issues');}
    private function slug(string $s):string{$s=iconv('UTF-8','ASCII//TRANSLIT',$s)?:$s;$s=preg_replace('/[^a-z0-9]+/i','-',strtolower($s));return trim($s,'-')?:'issue';}
}
